  atmospheric_bubble: {"id":"atmospheric_bubble","name":"Atmospheric Bubble","abilityType":"Magical","prerequisites":"2+ Skill Ranks in Use Magic","tpCost":10,"kpCost":"4(bT)","maneuverType":"Standard","actionCost":"1 Action","passiveBonus":null,"effect":"Protege contra ambientes irrespiráveis. Pague o custo em KP no início de cada turno para manter a proteção.","isSustained":true,"advancements":[{"id":"big_bubble","name":"Big Bubble","tpCost":5,"prerequisites":"3+ Skill Ranks in Use Magic","effect":"Pode estender a proteção a uma esfera. Cada rank de Use Magic acima de dois permite pagar mais 2(T) KP para subir uma magnitude."}],"restrictions":[]},
  barrier: {"id":"barrier","name":"Barrier","abilityType":"Technical/Magical","prerequisites":"Force or Magic Score of 4+","tpCost":15,"kpCost":"10(T)","maneuverType":"Counter","actionCost":"1 Counter Action","passiveBonus":null,"effect":"Ao receber um ataque, faça um Wound de Simple com qualquer Foundation e desconte o resultado do dano recebido.","advancements":[{"id":"efficient_barrier","name":"Efficient Barrier","tpCost":5,"prerequisites":"N/A","effect":"Reduz o custo em 2(T) KP."},{"id":"massive_barrier","name":"Massive Barrier","tpCost":15,"prerequisites":"Insight Score 6+","effect":"Por mais 4(T) KP, a redução vale para todos os atingidos pelo mesmo ataque em área."},{"id":"ally_barrier","name":"Ally Barrier","tpCost":15,"prerequisites":"Insight Score 6+","effect":"Pode proteger um aliado fora de Long Range. Você faz a rolagem, o aliado recebe a redução."}],"restrictions":[]},
  binding: {"id":"binding","name":"Binding","abilityType":"Technical/Magical","prerequisites":"Force or Magic Score of 8+","tpCost":20,"kpCost":"10(T)","maneuverType":"Standard","actionCost":"1 Action","minions":"Non-Minion","passiveBonus":null,"effect":"Contra um alvo fora de Long Range, vença Strike de Energy ou Magic contra Strike ou Dodge para reduzir a Defense Value dele em 1(T) até o fim do seu próximo turno. Um Might Clash adicional aplica Pinned. Pode pagar 2(T) KP para tirar metade do seu Might em LP ao prender e novamente a cada turno em que pagar a manutenção. A vítima ganha +1(T) cumulativo por turno no Might Clash para escapar, pelo Tier dela. Só mantenha um alvo e pode soltar como Instant.","isSustained":true,"advancements":[{"id":"psychic_grip","name":"Psychic Grip","tpCost":5,"prerequisites":"Telekinesis, Force or Magic Score 8+","effect":"O alvo preso tem −2(T) no Clash contra sua Telekinesis."},{"id":"binding_volley","name":"Binding Volley","tpCost":10,"prerequisites":"Force or Magic Score 10+","effect":"Dobre o gasto extra em KP para tirar seu Might inteiro em LP."},{"id":"binding_volleyball","name":"Binding Volleyball","tpCost":10,"prerequisites":"Binding Volley","effect":"Após Binding Volley, puxe o alvo para perto. Encadeie ataques Launching fora de sequência entre aliados não Minions, uma vez por participante. Se a vítima voltar a você, use Spike! (Super Mega Flare, +1 EC por acerto aliado) e encerre Pinned se acertar."},{"id":"energy_web","name":"Energy Web","tpCost":10,"prerequisites":"Insight Score 6+","effect":"Aplica Guard Down enquanto o alvo estiver Pinned por Binding."},{"id":"psycho_thread","name":"Psycho Thread","tpCost":10,"prerequisites":"Insight Score 10+","effect":"O alvo perde KP iguais à metade dos LP que você tirar com Binding."}],"restrictions":[{"id":"gentle_hold","name":"Gentle Hold","tpCost":-5,"lockedAdvancements":["Binding Volley","Psycho Thread"],"effect":"Elimina a opção de pagar KP para reduzir LP."},{"id":"weak_hold","name":"Weak Hold","tpCost":-5,"lockedAdvancements":["Energy Web","Binding Volleyball"],"effect":"Substitui Pinned por Guard Down em todos os efeitos da habilidade."}]},
  bluff_attack: {"id":"bluff_attack","name":"Bluff Attack","abilityType":"Technical/Magical","prerequisites":"2+ Skill Ranks in Bluff Skill","tpCost":15,"kpCost":"2(bT)","maneuverType":"Standard","actionCost":"1 Action","passiveBonus":"+1 ao Skill Bonus de Bluff.","effect":"Em Melee Range, dispute Bluff contra Bluff ou Intuition. Ao vencer, aplique Staggered até o fim do turno e Shaken até o fim do próximo turno do alvo. Se perder, provoque o Exploit dele.","advancements":[],"restrictions":[]},
  body_change: {"id":"body_change","name":"Body Change","abilityType":"Magical","prerequisites":"N/A","tpCost":50,"kpCost":"Your entire Capacity","maneuverType":"Standard","actionCost":"3 Actions","minions":"Non-Minion","passiveBonus":null,"effect":"Fora de Long Range, vença Cognitive contra Impulsive para trocar corpos e posições. Troque AG, TE, FO, MA, raça para requisitos, saves e LP, LP atuais após recalcular máximos, traços Body, Body Awakenings e equipamento. Preserve as escolhas de cada traço e respeite o limite de 5 traços (2 Primary e até 3 Secondary) e de Awakenings. Cada personagem ganha 3 Unfamiliar num corpo novo (−1(bT) a Combat Rolls e −1 Stress por stack, −1 Tier atual com 2+). Retire um stack no fim de cada encontro ou todos ao recuperar o próprio corpo.","advancements":[],"restrictions":[]},
  bound_battlefield: {"id":"bound_battlefield","name":"Bound Battlefield","abilityType":"Technical/Magical","prerequisites":"10+ Force or Magic Score","tpCost":20,"kpCost":"6(bT)","maneuverType":"Standard Maneuver","actionCost":"3 Actions","passiveBonus":null,"effect":"Crie Bound Squares em uma esfera Destructive centrada em você. A fronteira bloqueia a passagem nos dois sentidos e movimento forçado contra ela causa Collision de Hardness 3. Só pode haver um conjunto no campo. Pague 6(T) KP no início do turno. A barreira acaba ao sair dela, falhar Steadfast, ser Defeated ou deixar de pagar.","isSustained":true,"advancements":[{"id":"powerful_barrier","name":"Powerful Barrier","tpCost":12,"prerequisites":"12+ Force or Magic Score","effect":"Contra ataque que atravesse a fronteira, pode disputar Might com −1(T) por EC. Vitória protege os alvos do outro lado. Se o ataque perder todos os alvos, devolve ações ao atacante, mas consome o Ki."},{"id":"variable_battlefield","name":"Variable Battlefield","tpCost":8,"prerequisites":"8+ Insight Score","effect":"Escolha magnitude entre Standard e Destructive ao criar a barreira."},{"id":"shrinking_battlefield","name":"Shrinking Battlefield","tpCost":4,"prerequisites":"Variable Battlefield Advancement","effect":"Pague mais 2(bT) KP junto da manutenção para encolher uma magnitude. Os ocupantes da borda se deslocam uma casa para continuar dentro."}],"restrictions":[]},
  cage_of_light: {"id":"cage_of_light","name":"Cage of Light","abilityType":"Technical","prerequisites":"Force or Magic Score 10+, Insight Score 8+","tpCost":16,"kpCost":"10(T)","maneuverType":"Standard","actionCost":"All of your remaining Actions (Min. 2)","passiveBonus":null,"effect":"Crie uma esfera Large a até 8 casas. Quem esquiva dentro perde ¼ do seu Might em LP, arredondado para cima. Aproximar-se da borda custa o dobro do seu Might em LP. Cruzá-la exige vencer você em Might durante Movement. Mantenha com KP e todas as ações no início do turno, ou dispense como Instant.","isSustained":true,"advancements":[],"restrictions":[]},
  copy_being: {"id":"copy_being","name":"Copy Being","abilityType":"Magical","prerequisites":"4+ Skill Ranks in Use Magic","tpCost":50,"kpCost":"N/A","maneuverType":"Standard","actionCost":"3","minions":"Non-Minion","passiveBonus":null,"effect":"Uma vez por encontro, copie um personagem no campo que não seja Fusion. Use a ficha dele, inclusive Form e Enhancement ativos, com seu próprio Tier, LP, KP e Capacity atuais e máximos. Termine como Instant, ao fim do combate, em Defeated ou ao falhar Steadfast. Equipamento copiado desaparece e personagens internos da cópia não podem ser extraídos.","advancements":[],"restrictions":[]},
