  environment_shift: {"id":"environment_shift","name":"Environment Shift","abilityType":"Magical","prerequisites":"N/A","tpCost":10,"kpCost":"4(bT)","maneuverType":"Standard","actionCost":"1 Action","minions":"Non-Minion","passiveBonus":null,"effect":"Aplique Aflame, Bouncy, Dangerous, Electrified, Frozen ou Poisonous numa Sphere centrada em você até o seu próximo turno. Você ignora a qualidade escolhida, exceto Dangerous. Outros personagens na área podem gastar uma Counter Action para se mover fora de sequência.","advancements":[],"restrictions":[]},
  explosion_sorcery: {"id":"explosion_sorcery","name":"Explosion Sorcery","abilityType":"Magical","prerequisites":"2+ Skill Ranks in Use Magic","tpCost":20,"kpCost":"6(T) for each Action spent","maneuverType":"Standard","actionCost":"Variable (1~3 Actions)","minions":"Non-Minion","passiveBonus":null,"effect":"Escolha um alvo por ação e dispute Cognitive contra Cognitive, Impulsive ou Corporeal. Ao vencer, retire do alvo seus Magic Modifier em LP. Um Minion que não seja Special Minion sofre Defeated em vez disso.","advancements":[],"restrictions":[]},
