  fake_death: {"id":"fake_death","name":"Fake Death","abilityType":"Technical","prerequisites":"Personality Score 4+, 2+ Bluff Skill Ranks","tpCost":8,"kpCost":"4(bT)","maneuverType":"Out-of-Sequence","actionCost":"N/A","passiveBonus":null,"effect":"Uma vez por encontro, após receber dano de um ataque, pode cair Prone e disputar Bluff contra Intuition de todos os oponentes. Fique Hidden de quem perder. Movement acaba com esse disfarce.","advancements":[{"id":"surprise_strike","name":"Surprise Strike","tpCost":7,"prerequisites":"Insight Score 4+, Personality Score 6+","effect":"Se alguém Oblivious terminar o turno ao alcance enquanto você está Hidden, pode fazer Basic Attack fora de sequência e perder Hidden."},{"id":"stealth_crawl","name":"Stealth Crawl","tpCost":2,"prerequisites":"3+ Bluff Skill Ranks.","effect":"No início do turno, pode rastejar enquanto Hidden até seus ranks em Bluff em casas."},{"id":"like_the_dead","name":"Like the Dead","tpCost":4,"prerequisites":"Tenacity Score 7+","effect":"Se um oponente de quem você não está Hidden o acertar, pague 4(T) KP para disputar Bluff contra Intuition com +1d4 e se esconder dele se vencer."}],"restrictions":[]},
