  false_courage: {"id":"false_courage","name":"False Courage","abilityType":"Technical","prerequisites":"Personality Score of 4+","tpCost":8,"kpCost":"4(bT)","maneuverType":"Standard","actionCost":"1 Action","minions":"Free","passiveBonus":null,"effect":"Até o início do próximo turno, ganhe +2(T) Soak e sofra −1(T) a Combat Rolls.","advancements":[{"id":"bring_it_on","name":"Bring it On!","tpCost":12,"prerequisites":"Personality Score of 8+","effect":"Remove a penalidade a Combat Rolls."}],"restrictions":[]},
  finish_sign: {"id":"finish_sign","name":"Finish Sign","abilityType":"Technical","prerequisites":"Personality Score of 8+","tpCost":15,"kpCost":"4(bT)","maneuverType":"Standard Maneuver","actionCost":"2 Actions","minions":"Non-Minion","passiveBonus":null,"effect":"Declare uma Signature Technique e ganhe uma stack de Finisher a cada uso, até 7. Enquanto acumula, não use Energy Charge nem troque a técnica declarada. Ao usar a técnica, converta todas as stacks em EC. Elas contam para Mandatory Charge. Pode cancelar tudo como Instant.","advancements":[{"id":"aggressive_taunt","name":"Aggressive Taunt","tpCost":10,"prerequisites":"Insight Score of 8+","effect":"Se causou dano com dois ou mais ataques no turno, o custo cai para 1 ação até o fim desse turno."}],"restrictions":[]},
  flooding_technique: {"id":"flooding_technique","name":"Flooding Technique","abilityType":"Magical","prerequisites":"N/A","tpCost":15,"kpCost":"6(bT)","maneuverType":"Standard","actionCost":"2 Actions","passiveBonus":"Em Underwater, +1(T) a Combat Rolls.","effect":"Cria uma Large Sphere Underwater que acompanha seu deslocamento. Pague os KP a cada turno ou encerre. Pode encerrar como Instant e não pode criar outra área enquanto já houver uma.","isSustained":true,"advancements":[],"restrictions":[]},
